-- V11: wymogi formalne listy kontrolnej jako słownik (S-24, UC-06, ADR 0015): osobno Ts (skargi) i Tw (wnioski).
-- Kod stały (checklist_entry.requirement_code), treść/podstawa/warunek/kolejność edytowalne, pozycje wycofywane (active), nie usuwane.
-- Zasiew = dotychczasowa tabela DMN Dec_WymogiFormalne (treść do potwierdzenia przez Biuro Służby Prawnej).
CREATE TABLE formal_requirement (
  id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  symbol         VARCHAR(4)   NOT NULL,                  -- TS, TW
  code           VARCHAR(20)  NOT NULL,
  description    VARCHAR(600) NOT NULL,
  legal_basis    VARCHAR(160) NOT NULL,
  condition_code VARCHAR(30)  NOT NULL,                  -- ZAWSZE, BEZ_PELNOMOCNIKA, BRAK_ZASTEPSTWA
  position       INTEGER      NOT NULL,
  active         BOOLEAN      NOT NULL DEFAULT TRUE,
  created_by     VARCHAR(120) NOT NULL,
  created_at     TIMESTAMP WITH TIME ZONE NOT NULL,
  updated_by     VARCHAR(120),
  updated_at     TIMESTAMP WITH TIME ZONE,
  CONSTRAINT uq_formal_requirement UNIQUE (symbol, code)
);
CREATE INDEX ix_formal_requirement_symbol ON formal_requirement (symbol, active, position);

